 function cancelTravel(){if(tourFrame){cancelAnimationFrame(tourFrame);tourFrame=0;}}
 function easeJourney(t){let u=t;for(let i=0;i<6;i++){const x=3*(1-u)*(1-u)*u*.77+3*(1-u)*u*u*.175+u*u*u,dx=3*(1-u)*(1-u)*.77+6*(1-u)*u*(.175-.77)+3*u*u*(1-.175);if(Math.abs(dx)<.0001)break;u=clamp(u-(x-t)/dx);}return 3*u*u-2*u*u*u;}
 function travelTo(destination){cancelTravel();const origin=scrollY,started=performance.now(),duration=2700;function step(now){const t=clamp((now-started)/duration);scrollTo({top:origin+(destination-origin)*easeJourney(t),behavior:'instant'});if(t<1)tourFrame=requestAnimationFrame(step);else{tourFrame=0;schedule();}}tourFrame=requestAnimationFrame(step);}
 window.addEventListener('wheel',cancelTravel,{passive:true});window.addEventListener('touchstart',cancelTravel,{passive:true});window.addEventListener('pointerdown',cancelTravel,{passive:true});document.addEventListener('keydown',e=>{if(['Escape','ArrowDown','ArrowUp','PageDown','PageUp','Home','End',' '].includes(e.key))cancelTravel();});
